insert into public.categories (id, sort, name, blurb, tagline, lede, examples, hero_caption, intensity_min, intensity_max) values
  ('strength', 0, 'Strength', 'Barbells, kettlebells, coached lifts', 'Build the base.', 'Four classes, a coach at every rack. Learn the lift, then add the load.', 'Rib Rack Strength, Barbell Basics, Kettlebell Flow', 'Rib Rack Strength — coach spotting a back squat, 6:30 a.m.', 2, 5),
  ('cycle', 1, 'Cycle', 'Hills, rhythm and endurance on the bike', 'Ride the hills.', 'Three rides, five cycle studios. Pick a hill, a beat or a long road.', 'Climb Cycle, Rhythm Ride, Endurance 60', 'Cycle studio — riders, morning light through the windows', 2, 5),
  ('conditioning', 2, 'Conditioning', 'Intervals, running and bootcamp', 'Work hard, then stop.', 'Short, hard blocks with real rest. You leave tired and done.', 'Switchback HIIT, Canal Run Club, Bootcamp', 'Switchback HIIT — turf lane, first interval', 3, 5),
  ('mind-body', 3, 'Mind & Body', 'Yoga, pilates and breath work', 'Move slow, breathe well.', 'Four slow classes for joints, breath and a steady head. Most are good for a first visit.', 'Desert Flow Yoga, Mat Pilates, Mobility 30', 'Desert Flow Yoga — studio B, low sun on the floor', 1, 3),
  ('aqua', 4, 'Aqua', 'Lap swim, aqua fit and swim school', 'Water does half the work.', 'Lanes, classes and swim school at the three clubs with pools.', 'Lap Swim, Aqua Fit, Swim School', 'Lap lanes at Red Mountain under the shade sails', 1, 4),
  ('court', 5, 'Court', 'Pickleball, tennis and hoops', 'Play more than you plan.', 'Pickleball, tennis and hoops at Dobson, Red Mountain and Val Vista.', 'Pickleball Open Play, Clinic, Tennis Drills', 'Pickleball doubles, Red Mountain, 7 a.m.', 2, 4),
  ('recovery', 6, 'Recovery', 'Mobility, stretching and contrast therapy', 'Rest is a skill.', 'Stretch, heat, cold and compression. Rest, on the schedule.', 'Stretch & Release, Sauna + Plunge, Compression', 'Recovery lounge — sauna door open, soft light', 1, 1),
  ('youth', 7, 'Youth', 'Kids club, teen strength and juniors', 'Ages 6 months to 17.', 'Kids club, teen strength and junior pickleball. Coached, and a parent is always in the building.', 'Kids Club, Teen Strength, Junior Pickleball', 'Teen Strength — coach correcting a hip hinge', 1, 4);
insert into public.clubs (slug, sort, legacy_id, name, short_name, city, neighborhood, cross_streets, address, zip, phone, tel, club_type, type_label, sqft, opened, personality, intro, parking, access_notes, lat, lng, scene, tone, photo_caption, amenities, site_amenities, signature, extras, pool, courts, has, kids_club, recovery, studios, typical_weekday, typical_weekend, studio_count, demo_miles, demo_busyness, map_x, map_y) values
  ('mesa-dobson', 0, 'c1', 'Mesa – Dobson', 'Dobson', 'Mesa', 'Dobson', 'Dobson Rd & Southern Ave', 'Dobson Rd & Southern Ave, Mesa', '85202', '(480) 555-0114', '+14805550114', 'Flagship', 'Flagship · 68,000 sq ft', 68000, 2014, 'The big one. Bring the whole family.', 'Our first club and our largest. A lap pool and a warm-water therapy pool, four pickleball courts and two tennis courts, a full recovery suite, and a kids club. Plan on staying a while.', 'Free lot on the north side. Covered bays near the kids club door.', 'Step-free entrance on the east side. Lift access to the warm-water pool.', 33.384, -111.874, 'pool', 'teal', 'Dobson — family at the pool edge, 25-yd lanes behind, early light', array['25-yd lap pool, 8 lanes', 'Warm-water therapy pool', '4 pickleball courts', '2 tennis courts', 'Recovery suite', '3 studios + cycle studio', 'Kids club', 'Café']::text[], array['25-yd lap pool', 'Warm-water pool', '4 pickleball courts', '2 tennis courts', 'Recovery suite', 'Kids club', '3 studios + cycle studio', 'Café']::text[], array['25-yd lap pool', 'Warm-water pool', 'Recovery suite']::text[], 'Café', '{"label":"25-yard lap pool","lanes":8,"unit":"yd","therapy":true}'::jsonb, '[{"sport":"pickleball","count":4},{"sport":"tennis","count":2}]'::jsonb, '{"pool":true,"courts":true,"cycling":true,"kids":true,"recovery":true,"classes":true}'::jsonb, true, 'suite', array['Studio A', 'Studio B', 'Cycle Studio', 'Pool']::text[], array[1, 2, 3, 4, 3, 3, 3, 2, 3, 2, 2, 3, 4, 5, 4, 3, 2, 1]::smallint[], array[1, 1, 2, 3, 4, 4, 4, 3, 3, 2, 2, 2, 2, 2, 2, 1, 1, 1]::smallint[], 3, 11.3, 3, 62, 46),
  ('mesa-red-mountain', 1, 'c2', 'Mesa – Red Mountain', 'Red Mountain', 'Mesa', 'Red Mountain', 'Power Rd & McKellips Rd', 'Power Rd & McKellips Rd, Mesa', '85207', '(480) 555-0127', '+14805550127', 'Full club', 'Full club · 52,000 sq ft', 52000, 2017, 'Sunrise over the Superstitions, every morning.', 'An outdoor 25-m pool under shade sails, six pickleball courts, a turf lane and a cardio deck that faces the Superstition Mountains. The first class of the day starts as the sun clears the ridge.', 'Free lot on the west side. Shade is not guaranteed.', 'Step-free entrance on the south side. Accessible changing rooms.', 33.447, -111.69, 'outdoor-pool', 'copper', 'Red Mountain — outdoor pool under shade sails, 6 a.m., Superstition ridge soft behind', array['Outdoor 25-m pool, shade sails', '6 pickleball courts', 'Turf lane', '2 studios + cycle studio', 'Kids club', 'Superstition-view cardio deck']::text[], array['Outdoor 25-m pool', '6 pickleball courts', 'Turf lane', 'Kids club', '2 studios + cycle studio', 'Superstition-view cardio deck']::text[], array['Outdoor 25-m pool', '6 pickleball courts', 'Cardio deck']::text[], 'Superstition-view cardio deck, turf lane', '{"label":"25-metre outdoor pool","lanes":8,"unit":"m","outdoor":true}'::jsonb, '[{"sport":"pickleball","count":6}]'::jsonb, '{"pool":true,"courts":true,"cycling":true,"kids":true,"recovery":false,"classes":true}'::jsonb, true, 'none', array['Studio A', 'Studio B', 'Cycle Studio', 'Pool', 'Turf']::text[], array[2, 3, 4, 4, 3, 3, 2, 2, 3, 2, 2, 3, 4, 4, 5, 3, 2, 1]::smallint[], array[1, 1, 2, 3, 4, 4, 4, 3, 3, 2, 2, 2, 2, 2, 2, 1, 1, 1]::smallint[], 2, 13, 2, 80, 30),
  ('mesa-downtown', 2, 'c3', 'Mesa – Downtown', 'Downtown', 'Mesa', 'Downtown', 'Main St & Center St', 'Main St & Center St, Mesa', '85201', '(480) 555-0139', '+14805550139', 'Studio club', 'Studio club · 18,000 sq ft', 18000, 2020, 'In and out before your 8 a.m.', 'A compact studio club for people with a tight morning. A strength floor with racks, two studios, a cycle studio and a recovery lounge. No pool, no courts, no kids club.', 'Two hours free in the Center St garage. Bike racks at the door.', 'Step-free entrance on Main St. Lift to the second-floor studios.', 33.415, -111.832, 'lift', 'night', 'Downtown — strength floor at 7 a.m., window light across the racks', array['Strength floor', '2 studios + cycle studio', 'Recovery lounge (sauna, compression)']::text[], array['Strength floor', '2 studios', 'Cycle studio', 'Recovery lounge']::text[], array['Strength floor', 'Cycle studio', 'Recovery lounge']::text[], '—', null, '[]'::jsonb, '{"pool":false,"courts":false,"cycling":true,"kids":false,"recovery":true,"classes":true}'::jsonb, false, 'lounge', array['Studio A', 'Studio B', 'Cycle Studio']::text[], array[2, 3, 4, 5, 3, 2, 2, 2, 3, 3, 2, 3, 4, 5, 4, 3, 2, 1]::smallint[], array[1, 1, 2, 3, 4, 4, 4, 3, 3, 2, 2, 2, 2, 2, 2, 1, 1, 1]::smallint[], 2, 9.8, 4, 46, 52),
  ('gilbert-val-vista', 3, 'c4', 'Gilbert – Val Vista', 'Val Vista', 'Gilbert', 'Val Vista', 'Val Vista Dr & Warner Rd', 'Val Vista Dr & Warner Rd, Gilbert', '85233', '(480) 555-0142', '+14805550142', 'Full club', 'Full club · 60,000 sq ft', 60000, 2022, 'Swim school, courts, and a kids club that kids ask for.', 'A 25-yd lap pool, a splash pad and swim school, two basketball courts, four pickleball courts, a recovery suite and a kids club. The place for a family that trains in shifts.', 'Free lot on the east side. Drop-off lane at the kids club door.', 'Step-free entrance on the north side. Accessible changing rooms.', 33.336, -111.76, 'studio', 'gold', 'Val Vista — kids at the splash pad edge with a parent, pool behind, East Valley morning sun', array['25-yd lap pool, 6 lanes', 'Splash pad', 'Swim school', '2 basketball courts', '4 pickleball courts', 'Recovery suite', '3 studios + cycle studio', 'Kids club']::text[], array['25-yd lap pool', 'Splash pad', 'Swim school', '2 basketball courts', '4 pickleball courts', 'Recovery suite', 'Kids club', '3 studios + cycle studio']::text[], array['25-yd lap pool', 'Splash pad', 'Kids club']::text[], 'Splash pad, swim school', '{"label":"25-yard lap pool","lanes":6,"unit":"yd"}'::jsonb, '[{"sport":"pickleball","count":4},{"sport":"basketball","count":2}]'::jsonb, '{"pool":true,"courts":true,"cycling":true,"kids":true,"recovery":true,"classes":true}'::jsonb, true, 'suite', array['Studio A', 'Studio B', 'Cycle Studio', 'Pool', 'Court']::text[], array[1, 2, 4, 4, 3, 3, 2, 2, 3, 2, 2, 3, 4, 5, 5, 3, 2, 1]::smallint[], array[1, 1, 2, 3, 4, 4, 4, 3, 3, 2, 2, 2, 2, 2, 2, 1, 1, 1]::smallint[], 3, 1.7, 3, 58, 74),
  ('gilbert-heritage', 4, 'c5', 'Gilbert – Heritage', 'Heritage', 'Gilbert', 'Heritage', 'Gilbert Rd & Page Ave', 'Gilbert Rd & Page Ave, Gilbert', '85234', '(480) 555-0156', '+14805550156', 'Studio club', 'Studio club · 22,000 sq ft', 22000, 2024, 'Lifting platforms and a rooftop at golden hour.', 'A studio club built around lifting. Olympic platforms, a strength floor, two studios, a cycle studio, a recovery lounge and a rooftop mobility deck. No pool, no courts.', 'Free lot behind the building. Rooftop is reached by lift or stairs.', 'Step-free entrance on Gilbert Rd. Lift to the rooftop deck.', 33.354, -111.79, 'rooftop', 'plum', 'Heritage — rooftop mobility deck at golden hour, one member mid-stretch', array['Strength floor', 'Olympic lifting platforms', '2 studios + cycle studio', 'Recovery lounge', 'Rooftop mobility deck']::text[], array['Strength floor', 'Olympic lifting platforms', '2 studios', 'Cycle studio', 'Recovery lounge', 'Rooftop mobility deck']::text[], array['Olympic platforms', 'Rooftop mobility deck', 'Recovery lounge']::text[], 'Olympic platforms, rooftop mobility deck', null, '[]'::jsonb, '{"pool":false,"courts":false,"cycling":true,"kids":false,"recovery":true,"classes":true}'::jsonb, false, 'lounge', array['Studio A', 'Studio B', 'Cycle Studio', 'Rooftop']::text[], array[1, 1, 3, 4, 3, 2, 2, 2, 2, 2, 2, 3, 4, 4, 4, 3, 2, 1]::smallint[], array[1, 1, 2, 3, 4, 4, 4, 3, 3, 2, 2, 2, 2, 2, 2, 1, 1, 1]::smallint[], 2, 4.2, 2, 38, 82);
