  ('marisol', 'marisol-vega', 'Marisol Vega', 'Marisol', 'Cycle', 'CSCS · Spinning instructor', 8, null, array['gilbert-val-vista', 'mesa-dobson']::text[], true, true, array['Cycle', 'Strength basics', 'Return to training']::text[], array[]::text[], array['climb-cycle', 'rhythm-ride', 'endurance-60', 'barbell-basics']::text[], 'Climb Cycle', 'Marisol came to coaching from competitive cycling. She sets every bike herself and keeps the room kind. Quiet hands, strong legs.', 'Nobody climbs the same hill. I help you find your gear.', array[]::text[], array[]::text[], '[]'::jsonb, 'copper'),
