  ('luis', 'luis-ortega', 'Luis Ortega', 'Luis', 'Court', 'Swim coach · Red Cross lifeguard instructor', 4, null, array['mesa-red-mountain', 'gilbert-val-vista', 'mesa-dobson']::text[], true, false, array['Aqua', 'Youth']::text[], array[]::text[], array['swim-school', 'lap-swim', 'masters-swim', 'aqua-fit']::text[], 'Swim School', 'Luis runs swim school at Val Vista. He has taught more than a thousand children to float, and a few of their parents.', 'Every kid floats. It just takes a good day.', array[]::text[], array[]::text[], '[]'::jsonb, 'teal'),
  ('hannah', 'hannah-cole', 'Hannah Cole', 'Hannah', 'Youth', '', 3, null, array['gilbert-val-vista']::text[], true, false, array[]::text[], array[]::text[], array[]::text[], '', '', '', array[]::text[], array[]::text[], '[]'::jsonb, ''),
