  ('devon', 'devon-hart', 'Devon Hart', 'Devon', 'Cycle', 'NSCA-CPT · Olympic lifting', 4, null, array['gilbert-val-vista', 'gilbert-heritage', 'mesa-downtown', 'mesa-dobson']::text[], true, true, array['Strength', 'Olympic lifting']::text[], array[]::text[], array['rib-rack-strength', 'olympic-lifting-club', 'switchback-hiit', 'kettlebell-flow']::text[], 'Olympic Lifting Club', 'Devon coaches the platforms at Heritage. He teaches the pull first and the load last, and he writes down your numbers.', 'Technique is the cheapest plate you can add.', array[]::text[], array[]::text[], '[]'::jsonb, 'night'),
  ('jamal', 'jamal-carter', 'Jamal Carter', 'Jamal', 'Cycle', '', 6, null, array['mesa-dobson', 'mesa-red-mountain']::text[], true, false, array[]::text[], array[]::text[], array[]::text[], '', '', '', array[]::text[], array[]::text[], '[]'::jsonb, ''),
  ('elise', 'elise-moreno', 'Elise Moreno', 'Elise', 'Mind & Body', '', 7, null, array['mesa-downtown', 'mesa-dobson', 'mesa-red-mountain']::text[], true, false, array[]::text[], array[]::text[], array[]::text[], '', '', '', array[]::text[], array[]::text[], '[]'::jsonb, ''),
  ('owen', 'owen-kim', 'Owen Kim', 'Owen', 'Conditioning', '', 5, null, array['mesa-downtown', 'mesa-dobson', 'mesa-red-mountain']::text[], true, false, array[]::text[], array[]::text[], array[]::text[], '', '', '', array[]::text[], array[]::text[], '[]'::jsonb, ''),
