  ('gabe', 'gabe-santos', 'Gabe Santos', 'Gabe', 'Swim school', '', 6, null, array['gilbert-val-vista']::text[], true, false, array[]::text[], array[]::text[], array[]::text[], '', '', '', array[]::text[], array[]::text[], '[]'::jsonb, ''),
  ('hector', 'hector-vance', 'Hector Vance', 'Hector', 'Masters swim', '', 11, null, array['mesa-dobson', 'gilbert-val-vista', 'mesa-red-mountain']::text[], true, false, array[]::text[], array[]::text[], array[]::text[], '', '', '', array[]::text[], array[]::text[], '[]'::jsonb, ''),
  ('tessa', 'tessa-lund', 'Tessa Lund', 'Tessa', 'Strength', '', 5, null, array['mesa-dobson', 'mesa-red-mountain']::text[], true, false, array[]::text[], array[]::text[], array[]::text[], '', '', '', array[]::text[], array[]::text[], '[]'::jsonb, ''),
  ('sam', 'sam-okafor', 'Sam Okafor', 'Sam', '', 'NASM-CPT · Youth fitness', 7, 2014, array['mesa-dobson', 'mesa-red-mountain', 'gilbert-val-vista']::text[], false, true, array['Return to training', 'Strength']::text[], array['Return to training', 'Strength']::text[], array['teen-strength', 'barbell-basics', 'junior-pickleball']::text[], 'Teen Strength', 'I help people come back after surgery or a long break. We start with what your body can do today. No lectures.', 'Teens do not need hype. They need a plan.', array['Returning after injury', 'Knee and hip', 'First-time training', 'Over 50']::text[], array['10 minutes talking', '25 minutes moving', '10 minutes plan']::text[], '[{"dow":2,"time":"09:30"},{"dow":4,"time":"09:30"},{"dow":4,"time":"10:15"},{"dow":4,"time":"13:00"},{"dow":4,"time":"16:30"},{"dow":5,"time":"10:15"},{"dow":6,"time":"08:00"},{"dow":2,"time":"13:00"}]'::jsonb, 'gold'),
  ('elena', 'elena-duarte', 'Elena Duarte', 'Elena', '', '', null, 2016, array['gilbert-heritage', 'mesa-downtown']::text[], false, true, array['Olympic lifting', 'Barbell strength']::text[], array['Olympic lifting', 'Strength']::text[], array[]::text[], '', 'Snatch, clean and jerk, taught in small pieces. Bring your current lifts. We build from there.', '', array['Learning the Olympic lifts', 'Barbell technique', 'Strength plateaus']::text[], array['10 minutes goals and history', '30 minutes technique', '5 minutes plan']::text[], '[{"dow":3,"time":"06:30"},{"dow":3,"time":"17:30"},{"dow":5,"time":"06:30"},{"dow":1,"time":"06:30"},{"dow":6,"time":"09:00"}]'::jsonb, ''),
  ('marcus', 'marcus-hale', 'Marcus Hale', 'Marcus', '', '', null, 2012, array['gilbert-val-vista', 'mesa-dobson']::text[], false, true, array['Swim technique', 'Masters swim']::text[], array['Swim']::text[], array[]::text[], '', 'Most swimmers are one fix away from a faster, easier lap. We film your stroke and fix the biggest thing first.', '', array['Adult learn-to-swim', 'Stroke fixes', 'Triathlon swims']::text[], array['10 minutes goals', '30 minutes in the water', '5 minutes homework']::text[], '[{"dow":5,"time":"07:15"},{"dow":5,"time":"08:15"},{"dow":2,"time":"07:15"},{"dow":6,"time":"07:00"},{"dow":3,"time":"17:45"}]'::jsonb, ''),
  ('rosa', 'rosa-lindgren', 'Rosa Lindgren', 'Rosa', '', '', null, 2018, array['mesa-red-mountain']::text[], false, true, array['Mobility', 'Pickleball conditioning', 'Older adults']::text[], array['Mobility', 'Pickleball']::text[], array[]::text[], '', 'Pickleball is a lot of lunging. I build the hips, ankles and shoulders that let you play four mornings a week.', '', array['Pickleball players', 'Older adults', 'Balance and mobility']::text[], array['10 minutes movement screen', '25 minutes work', '10 minutes plan']::text[], '[{"dow":3,"time":"09:00"},{"dow":3,"time":"10:00"},{"dow":5,"time":"09:00"},{"dow":1,"time":"11:00"}]'::jsonb, ''),
  ('jake', 'jake-whitcomb', 'Jake Whitcomb', 'Jake', '', '', null, 2019, array['gilbert-val-vista']::text[], false, true, array['Youth and teen athletic development']::text[], array['Youth and teen']::text[], array[]::text[], '', 'Teens get stronger by learning to move well first. Parents are welcome to watch the first session.', '', array['Ages 13 to 17', 'School sports', 'First time in a weight room']::text[], array['10 minutes goals', '30 minutes movement', '5 minutes plan']::text[], '[{"dow":4,"time":"16:00"},{"dow":2,"time":"16:00"},{"dow":6,"time":"10:00"},{"dow":3,"time":"16:30"}]'::jsonb, ''),
  ('imani', 'imani-brooks', 'Imani Brooks', 'Imani', '', 'RYT-500', 12, null, array['gilbert-val-vista', 'mesa-dobson']::text[], false, true, array['Mind & Body', 'Return to training', 'Mobility']::text[], array[]::text[], array['desert-flow-yoga', 'mat-pilates', 'mobility-30', 'breathwork']::text[], 'Desert Flow Yoga', 'Imani teaches yoga, mobility and breathwork. She works with members who are returning after injury and never rushes a first week.', 'Slow is allowed here.', array[]::text[], array[]::text[], '[]'::jsonb, 'sage'),
  ('tess', 'tess-nakamura', 'Tess Nakamura', 'Tess', '', 'ACE-CPT · Group cycling', 8, null, array['mesa-red-mountain']::text[], false, true, array['Cycle', 'Conditioning']::text[], array[]::text[], array['climb-cycle', 'endurance-60', 'bootcamp', 'canal-run-club']::text[], 'Endurance 60', 'Tess leads the 5:45 a.m. rides at Red Mountain and the Saturday run along the canal.', 'Show up. We will take it from there.', array[]::text[], array[]::text[], '[]'::jsonb, 'rose'),
  ('ray', 'ray-delgado', 'Ray Delgado', 'Ray', '', 'USAPA pickleball coach', 10, null, array['mesa-red-mountain', 'mesa-dobson']::text[], false, false, array['Court', 'Return to training']::text[], array[]::text[], array['pickleball-open-play', 'pickleball-clinic', 'tennis-drills']::text[], 'Pickleball Clinic', 'Ray coaches pickleball and keeps the beginner court friendly. He plays four mornings a week himself.', 'Play more than you plan.', array[]::text[], array[]::text[], '[]'::jsonb, 'sand'),
  ('nadia', 'nadia-kowalski', 'Nadia Kowalski', 'Nadia', '', 'DPT · Recovery coach', 13, null, array['mesa-dobson', 'gilbert-val-vista']::text[], false, true, array['Recovery', 'Return to training']::text[], array[]::text[], array['stretch-and-release', 'compression', 'sauna-plunge']::text[], 'Stretch & Release', 'Nadia is a physical therapist who runs the recovery spaces. She helps members plan a first week back.', 'Rest is part of the plan, not a break from it.', array[]::text[], array[]::text[], '[]'::jsonb, 'plum');
insert into public.class_types (key, slug, sort, name, category_id, duration, intensity, intensity_min, intensity_max, capacity, unit, first_timer_ok, teen_ok, min_age, bookable, about, blurb, bring, equipment_note, group_label, club_slugs, pick, gear, caption) values
  ('rrs', 'rib-rack-strength', 0, 'Rib Rack Strength', 'strength', 60, 4, 3, 5, 14, 'spots', false, false, 16, true, 'Squat, press, pull. Five lifts built on one rack, coached in small groups. Pick your own weight; the coach sets the tempo.', 'Squat, press and pull in small groups, with a coach at the rack.', array['Water', 'Towel', 'Lifting shoes optional']::text[], '', 'Up to 14', null, 'Pick this if you like a plan and a barbell.', 'Water bottle, towel, shoes you can move in.', 'Rib Rack Strength — class in progress, faces visible, natural light'),
  ('bb', 'barbell-basics', 1, 'Barbell Basics', 'strength', 60, 2, 2, 3, 12, 'spots', true, false, 16, true, 'Learn the bar. Hips, hinge, press and row with a light barbell and plenty of cues. A good first strength class.', 'Learn the squat, hinge and press with an empty bar. Form first.', array['Water', 'Towel']::text[], '', 'Up to 12', null, 'Pick this if you have never lifted.', 'Water bottle, towel, shoes you can move in.', 'Barbell Basics — class in progress, faces visible, natural light'),
  ('kf', 'kettlebell-flow', 2, 'Kettlebell Flow', 'strength', 45, 3, 3, 4, 16, 'spots', false, true, 13, true, 'Swings, carries and getups linked into one flowing circuit. Light bells are fine.', 'Swings, goblet squats and carries in a steady circuit.', array['Water', 'Towel']::text[], '', 'Up to 16', null, 'Pick this if you want strength without a rack.', 'Water bottle, towel, shoes you can move in.', 'Kettlebell Flow — class in progress, faces visible, natural light'),
  ('ofl', 'olympic-lifting-club', 3, 'Olympic Lifting Club', 'strength', 75, 4, 4, 5, 10, 'spots', false, false, 16, true, 'Open coaching on the platforms. Bring a plan or ask for one. Heritage only.', 'Snatch and clean-and-jerk technique on the platforms.', array['Lifting shoes', 'Chalk is provided']::text[], '', 'Up to 10', array['gilbert-heritage', 'mesa-dobson']::text[], 'Pick this if you already lift and want technique.', 'Water bottle, towel, shoes you can move in.', 'Olympic Lifting Club — class in progress, faces visible, natural light'),
  ('cc', 'climb-cycle', 4, 'Climb Cycle', 'cycle', 45, 4, 4, 4, 20, 'bikes', true, true, 13, true, 'Hills, not hype. Climb Cycle follows a mountain profile: warm-up, three climbs, a long descent. Set your own resistance. Nobody checks.', 'Rolling hills on a bike. Heavy resistance, seated and standing climbs, and a long final push.', array['Water', 'Towel', 'Cycling shoes optional']::text[], '', 'Up to 20 riders', null, 'Pick this if you like to push.', 'Bike, water bottle, towel. Shoes optional.', 'Climb Cycle — riders from behind, a coach''s cue visible, morning light across the studio'),
  ('ride', 'rhythm-ride', 5, 'Rhythm Ride', 'cycle', 45, 3, 3, 3, 20, 'bikes', false, true, 13, true, 'Ride to the beat. Steady cadence, lots of seated work, and a playlist you can feel in your legs.', 'Pedal to the beat in a dark studio. Light climbs, big choruses.', array['Water', 'Towel']::text[], '', 'Up to 20 riders', null, 'Pick this if you like music.', 'Water bottle, towel, shoes you can move in.', 'Rhythm Ride — class in progress, faces visible, natural light'),
  ('e60', 'endurance-60', 6, 'Endurance 60', 'cycle', 60, 3, 2, 3, 18, 'bikes', false, false, 14, true, 'One hour of aerobic work at a pace you can hold. Good Saturday legs.', 'One steady hour in the saddle. Settle in and hold a pace.', array['Water', 'Towel', 'Cycling shoes optional']::text[], '', 'Up to 18 riders', null, 'Pick this if you like to settle in.', 'Water bottle, towel, shoes you can move in.', 'Endurance 60 — class in progress, faces visible, natural light'),
  ('sbh', 'switchback-hiit', 7, 'Switchback HIIT', 'conditioning', 30, 5, 5, 5, 20, 'spots', false, false, 16, true, 'Thirty minutes of work and rest, in switchbacks. Intervals scale to you. All-out means your all-out.', 'Short, hard intervals with real rest. Sleds, rowers and bodyweight.', array['Water', 'Towel']::text[], '', 'Up to 20', null, 'Pick this if you like a short, hard hour.', 'Water bottle, towel, shoes you can move in.', 'Switchback HIIT — class in progress, faces visible, natural light'),
  ('crc', 'canal-run-club', 8, 'Canal Run Club', 'conditioning', 45, 3, 3, 4, 25, 'spots', false, true, 14, true, 'Out and back on the canal path. Three paces, one meeting point, nobody left behind.', 'A coached group run on the canal path. Three paces, nobody dropped.', array['Water', 'Running shoes']::text[], '', 'Open', array['mesa-red-mountain', 'gilbert-val-vista', 'gilbert-heritage']::text[], 'Pick this if you like to run with people.', 'Water bottle, towel, shoes you can move in.', 'Canal Run Club — class in progress, faces visible, natural light'),
  ('bc', 'bootcamp', 9, 'Bootcamp', 'conditioning', 45, 4, 4, 4, 22, 'spots', false, false, 16, true, 'Stations, sleds and a friendly drill sergeant who also says please.', 'Circuits on the turf lane: pushes, pulls, carries, sprints.', array['Water', 'Towel']::text[], '', 'Up to 22', null, 'Pick this if you like variety.', 'Water bottle, towel, shoes you can move in.', 'Bootcamp — class in progress, faces visible, natural light'),
  ('dfy', 'desert-flow-yoga', 10, 'Desert Flow Yoga', 'mind-body', 60, 2, 2, 2, 20, 'mats', true, true, 13, true, 'A slow vinyasa with long holds. Mats and blocks are provided. Finish with five quiet minutes.', 'A flowing vinyasa class. Strong holds, slow breath, a long rest at the end.', array['Water', 'Mat if you prefer your own']::text[], '', 'Up to 20', null, 'Pick this if you want to stretch and sweat a little.', 'Mat (we have loaners), water.', 'Desert Flow Yoga — class in progress, faces visible, natural light'),
  ('mp', 'mat-pilates', 11, 'Mat Pilates', 'mind-body', 50, 2, 2, 3, 18, 'mats', true, true, 13, true, 'Core, hips and posture on the mat. Small movements, done well.', 'Core and hip work on the mat. Small movements, a lot of control.', array['Water', 'Towel']::text[], '', 'Up to 18', null, 'Pick this if you want a stronger center.', 'Water bottle, towel, shoes you can move in.', 'Mat Pilates — class in progress, faces visible, natural light'),
  ('m30', 'mobility-30', 12, 'Mobility 30', 'mind-body', 30, 1, 1, 1, 24, 'mats', true, true, 13, true, 'Thirty minutes of hips, shoulders and spine. The class you take after the class you took.', 'Thirty minutes of joint prep and gentle stretching. Good before a lift or after surgery.', array['Water', 'Towel']::text[], '', 'Up to 24', null, 'Pick this if you are coming back from an injury.', 'Water bottle, towel, shoes you can move in.', 'Mobility 30 — class in progress, faces visible, natural light'),
  ('bw', 'breathwork', 13, 'Breathwork', 'mind-body', 30, 1, 1, 1, 20, 'mats', true, true, 13, true, 'Thirty minutes lying down, breathing on purpose. Quiet room, no pretzels.', 'Guided breathing and a long rest. Lie down. We do the talking.', array['Water', 'Towel']::text[], '', 'Up to 20', null, 'Pick this if you want to slow down.', 'Water bottle, towel, shoes you can move in.', 'Breathwork — class in progress, faces visible, natural light'),
  ('lap-swim', 'lap-swim', 14, 'Lap Swim', 'aqua', 45, 4, 2, 4, 2, 'lanes', true, false, 0, false, 'Reserve a lane in a 45-minute slot. Up to two swimmers share a lane.', 'Reserve a lane in a 45-minute slot. Up to two swimmers share a lane.', array[]::text[], '', '2 per lane', array['mesa-dobson', 'mesa-red-mountain', 'gilbert-val-vista']::text[], 'Pick this if you swim on your own.', 'Water bottle, towel, shoes you can move in.', 'Lap Swim — class in progress, faces visible, natural light'),
  ('af', 'aqua-fit', 15, 'Aqua Fit', 'aqua', 45, 2, 1, 2, 16, 'spots', true, true, 14, true, 'Low-impact cardio in the pool. Easy on knees and hips, harder than it looks.', 'Low-impact cardio and strength in the water. The water holds you up.', array['Swimsuit', 'Towel', 'Water']::text[], '', 'Up to 16', array['mesa-dobson', 'mesa-red-mountain', 'gilbert-val-vista']::text[], 'Pick this if your joints want a break.', 'Water bottle, towel, shoes you can move in.', 'Aqua Fit — class in progress, faces visible, natural light'),
  ('ss', 'swim-school', 16, 'Swim School', 'aqua', 30, 2, 1, 2, 8, 'spots', true, true, 4, true, 'Small-group lessons for children 4 to 12, grouped by level. A parent stays on the deck.', 'Five levels from Splash to Lap-ready, taught by Red Cross-certified coaches.', array['Swimsuit', 'Towel', 'Goggles']::text[], '', 'Up to 6 per coach', array['gilbert-val-vista']::text[], 'Pick this if your child is learning to swim.', 'Water bottle, towel, shoes you can move in.', 'Swim School — class in progress, faces visible, natural light'),
  ('ms', 'masters-swim', 17, 'Masters Swim', 'aqua', 60, 4, 3, 4, 12, 'spots', false, false, 18, true, 'Coached lap sets for adult swimmers. Three lanes by pace. Bring a pull buoy.', 'Coached laps with a written set. For adults who already swim.', array['Swimsuit', 'Goggles', 'Pull buoy']::text[], '', 'Up to 12', array['mesa-dobson', 'mesa-red-mountain', 'gilbert-val-vista']::text[], 'Pick this if you want a set to follow.', 'Water bottle, towel, shoes you can move in.', 'Masters Swim — class in progress, faces visible, natural light'),
  ('pop', 'pickleball-open-play', 18, 'Pickleball Open Play', 'court', 120, 3, 2, 3, 24, 'spots', false, true, 14, true, 'Drop in and rotate. Courts are sorted by level. Paddle rack by the door.', 'Rotate in and play. Ask a coach for a beginner court.', array['Court shoes', 'Paddle']::text[], '', 'Open', array['mesa-dobson', 'mesa-red-mountain', 'gilbert-val-vista']::text[], 'Pick this if you just want to play.', 'Water bottle, towel, shoes you can move in.', 'Pickleball Open Play — class in progress, faces visible, natural light'),
  ('pcl', 'pickleball-clinic', 19, 'Pickleball Clinic', 'court', 90, 3, 2, 3, 12, 'spots', true, true, 14, true, 'Drills for the dink, the third shot and where to stand. Paddles are provided.', 'Drills for dinks, drops and serves, then games to 11.', array['Court shoes', 'Water']::text[], '', 'Up to 12', array['mesa-dobson', 'mesa-red-mountain', 'gilbert-val-vista']::text[], 'Pick this if you want to get better.', 'Water bottle, towel, shoes you can move in.', 'Pickleball Clinic — class in progress, faces visible, natural light'),
  ('td', 'tennis-drills', 20, 'Tennis Drills', 'court', 60, 3, 3, 4, 12, 'spots', false, false, 14, true, 'Forehands, backhands and footwork with a coach and a hopper of balls.', 'Feed-and-hit drills with a coach. All levels.', array['Racquet', 'Court shoes']::text[], '', 'Up to 12', array['mesa-dobson']::text[], 'Pick this if you play tennis.', 'Water bottle, towel, shoes you can move in.', 'Tennis Drills — class in progress, faces visible, natural light'),
  ('hr', 'hoops-run', 21, 'Hoops Run', 'court', 90, 4, 3, 4, 20, 'spots', false, false, 16, true, 'Full-court pickup, refereed lightly. Winners stay on.', 'Pick-up basketball on two full courts.', array['Court shoes', 'Water']::text[], '', 'Open', array['gilbert-val-vista']::text[], 'Pick this if you like to run the floor.', 'Water bottle, towel, shoes you can move in.', 'Hoops Run — class in progress, faces visible, natural light'),
  ('sr', 'stretch-and-release', 22, 'Stretch & Release', 'recovery', 30, 1, 1, 1, 20, 'mats', true, false, 16, true, 'Long stretches with foam rollers and bands. Recovery for the legs you used yesterday.', 'Guided stretching and foam rolling. Ends with five quiet minutes.', array['Water', 'Towel']::text[], '', 'Up to 20', null, 'Pick this if you are sore.', 'Water bottle, towel, shoes you can move in.', 'Stretch & Release — class in progress, faces visible, natural light'),
  ('sauna-plunge', 'sauna-plunge', 23, 'Sauna + Plunge', 'recovery', 30, 1, 1, 1, 8, 'spots', true, false, 0, false, 'A 30-minute slot for heat and cold in the recovery space. Ages 18 and up.', 'A 30-minute slot for heat and cold in the recovery space. Ages 18 and up.', array[]::text[], '', 'Up to 8', array['mesa-dobson', 'gilbert-val-vista']::text[], 'Pick this if you have Summit and a sore week.', 'Water bottle, towel, shoes you can move in.', 'Sauna + Plunge — class in progress, faces visible, natural light'),
  ('compression', 'compression', 24, 'Compression', 'recovery', 30, 1, 1, 1, 6, 'spots', true, false, 0, false, 'Air boots for tired legs. Sit, read, leave lighter.', 'Air boots for tired legs. Sit, read, leave lighter.', array[]::text[], '', 'Up to 6', array['mesa-dobson', 'mesa-downtown', 'gilbert-val-vista', 'gilbert-heritage']::text[], 'Pick this if you run or lift most days.', 'Water bottle, towel, shoes you can move in.', 'Compression — class in progress, faces visible, natural light'),
  ('kids-club', 'kids-club', 25, 'Kids Club', 'youth', 120, 2, 1, 2, 8, 'spots', true, true, 0, false, 'Play, crafts and games for ages 6 months to 12 years, in 2-hour blocks.', 'Play, crafts and games for ages 6 months to 12 years, in 2-hour blocks.', array[]::text[], '', 'Staffed 1 to 8', array['mesa-dobson', 'mesa-red-mountain', 'gilbert-val-vista']::text[], 'Pick this if you want to train while they play.', 'Water bottle, towel, shoes you can move in.', 'Kids Club — class in progress, faces visible, natural light'),
  ('ts', 'teen-strength', 26, 'Teen Strength', 'youth', 60, 3, 2, 4, 12, 'spots', true, true, 13, true, 'Strength basics for ages 13 to 17. Movement first, weight second. Coached by Hannah Cole.', 'Coached barbell and bodyweight basics for ages 13 to 17. Form first.', array['Water', 'Closed-toe shoes']::text[], '', 'Up to 12', array['gilbert-val-vista', 'mesa-dobson']::text[], 'Pick this if your teen wants a place that is not a screen.', 'Water, trainers.', 'Teen Strength — class in progress, faces visible, natural light'),
  ('jp', 'junior-pickleball', 27, 'Junior Pickleball', 'youth', 60, 2, 2, 3, 8, 'spots', true, true, 8, true, 'Ages 8 to 14. Small courts, soft balls, loud cheering.', 'A clinic for ages 8 to 14. Games, rules and manners.', array['Court shoes']::text[], '', 'Up to 8', array['mesa-dobson', 'mesa-red-mountain', 'gilbert-val-vista']::text[], 'Pick this if your child wants to play the family sport.', 'Water bottle, towel, shoes you can move in.', 'Junior Pickleball — class in progress, faces visible, natural light');
