insert into public.faqs (id, audience, sort, group_name, question, answer) values
  ('site-card', 'site', 0, 'Getting started', 'Do I need a card for a tour or a pass?', 'No. Tours and the 3-day pass are free. We do not ask for a card.'),
  ('site-bring', 'site', 1, 'Getting started', 'What should I bring on my first visit?', 'Photo ID, if you want a 3-day pass. Wear what you move in. Bring a water bottle. We have towels for Summit members.'),
  ('site-injury', 'site', 2, 'Getting started', 'I am new or coming back from an injury. Where do I start?', 'Book a tour and tell us. We match you with a coach and an easy class. Many members start with Mobility 30 or Aqua Fit.'),
  ('site-contract', 'site', 3, 'Memberships', 'Is there a contract?', 'No. Memberships are month to month.'),
  ('site-cancel', 'site', 4, 'Memberships', 'How do I cancel or freeze?', 'Give 30 days'' notice in the app or at the desk. A freeze costs $10 a month for 1 to 3 months.'),
  ('site-fees', 'site', 5, 'Memberships', 'What fees are there besides the monthly price?', 'Enrollment is $0 during Fall climb (otherwise $49). A $49 annual facility fee is charged in March.'),
  ('site-booking', 'site', 6, 'Memberships', 'What are the booking rules?', 'Book up to 7 days ahead (Summit: 9). Cancel free up to 2 hours before. Later is a late cancel. Three late cancels in 30 days pause booking for 3 days. Waitlists move up until 1 hour before class.'),
  ('site-kids-ages', 'site', 7, 'Kids and teens', 'What ages can use kids club?', 'Ages 6 months to 12 years, in 2-hour blocks. A parent checks in at the same club and stays in the building.'),
  ('site-teen', 'site', 8, 'Kids and teens', 'Can my teen train here?', 'Yes. Teens 13 to 17 can book classes marked Teen OK, such as Teen Strength. A parent signs the waiver and manages billing. Strength floor use without a coach starts at age 16. Sauna and cold plunge are for ages 18 and up.'),
  ('site-age-limit', 'site', 9, 'Kids and teens', 'Is there an age limit for members?', 'Adults of any age can join. We have easy classes, a warm-water pool and coaches who work with older members.'),
  ('home-faq-card', 'home', 0, '', 'Do I need a card for a tour or a pass?', 'No. Tours and the 3-day pass are free and need no card.'),
  ('home-faq-contract', 'home', 1, '', 'Is there a contract?', 'No. Memberships are month to month. Cancel or freeze with 30 days'' notice.'),
  ('home-faq-clubs', 'home', 2, '', 'Can I use more than one club?', 'Ridge and Summit work at all 5 clubs. Trailhead works at your home club.'),
  ('home-faq-kids', 'home', 3, '', 'Is there something for my kids?', 'Yes. Kids club at Mesa – Dobson, Mesa – Red Mountain and Gilbert – Val Vista.'),
  ('home-faq-injury', 'home', 4, '', 'I am new or coming back from an injury. Where do I start?', 'Book a tour and tell us. We will match you with a coach and an easy class.'),
  ('member-1', 'member', 1, 'Booking and cancelling', 'How far ahead can I book?', 'Classes open 7 days ahead (Summit: 9 days) at 6:00 a.m. Arizona time on the opening day. Courts open 3 days ahead.'),
  ('member-2', 'member', 2, 'Booking and cancelling', 'How do late cancels work?', 'Cancel free up to 2 hours before start. Later counts as a late cancel. Three late cancels in 30 days pause new class, court and lane booking for 3 days. A no-show counts as a late cancel. Kids club has no strikes.'),
  ('member-3', 'member', 3, 'Booking and cancelling', 'What happens when a class is full?', 'Join the waitlist (up to 5 at once). When a spot opens you get a push and 30 minutes to tap Confirm spot. We stop moving people up 1 hour before class; after that, open spots show as drop-in spots.'),
  ('member-4', 'member', 4, 'Courts and lanes', 'How do court reservations work?', 'Courts come with Ridge and Summit. Reserve 60 or 90 minutes, up to 3 days ahead. One court per day and two active at a time. Cancel free until 2 hours before.'),
  ('member-5', 'member', 5, 'Courts and lanes', 'Can I share a lane?', 'Yes. Up to 2 swimmers share a lane, in circle swim. Lane slots are 45 minutes. Lap lanes have no waitlist.'),
  ('member-6', 'member', 6, 'Kids club', 'Who can go to kids club?', 'Children from 6 months to 12 years. Blocks are 2 hours, Monday to Saturday. A parent checks in at the same club and stays in the club. An unclaimed block is released 15 minutes after it starts.'),
  ('member-7', 'member', 7, 'Billing', 'When am I charged?', 'On your billing day each month. The $49 annual facility fee is charged in March. If a payment fails we retry on day 3 and day 6, and you keep full access through day 7.'),
  ('member-8', 'member', 8, 'Membership', 'How do I freeze?', 'Freeze for 1, 2 or 3 months at $10 per month. A freeze starts on the first billing date at least 30 days after you ask.'),
  ('member-9', 'member', 9, 'Membership', 'How do I cancel?', 'Cancel from Membership with 30 days'' notice. You keep full access until the end date and can keep your membership with one click until then.'),
  ('member-10', 'member', 10, 'Guest passes', 'Who can I bring?', 'Guests are 18 or older, or 16 and 17 with a parent or guardian waiver. A pass is good for one visit at one club and lasts 14 days. Ridge includes 1 per month, Summit 4.');
insert into public.journal_posts (slug, published_on, title, dek, category, author_slug, read_minutes, tone, caption, class_slug, sections) values
  ('your-first-climb-cycle', '2026-10-12', 'Your first Climb Cycle: five things to know', 'Heavy load, short hills and a coach calling the numbers. Here is how to get through your first 45 minutes.', 'Train', 'marisol-vega', 6, 'sage', 'Cycle studio at Val Vista, riders mid-climb, 6 a.m.', 'climb-cycle', '[["Arrive early","Show up 10 minutes before class. A coach sets your seat and handlebars. Ask for the set-up, even if you think you know it. A bike that fits makes the hour easier."],["Pick a load you can talk over","The coach calls out loads from 1 to 10. Start at 3 or 4. You can always add. You cannot easily take away halfway up a hill."],["Stand when you are told, not before","Standing climbs are short. Sit when your legs say sit. Nobody is watching your cadence."],["Drink early","It is Arizona. Water before class, a sip every few minutes, and more after."],["Come back on Thursday","The second class is easier than the first. The third is where it starts to feel like yours."]]'::jsonb),
  ('a-week-back-after-surgery', '2026-10-05', 'A first week back after surgery', 'What a coach looks for, what to skip, and why the warm pool is a good first stop.', 'Train', 'imani-brooks', 7, 'teal', 'Warm-water pool at Dobson, a member and a coach', 'mobility-30', '[["Ask your surgeon first","Get a clear yes, and ask what to avoid. Bring the notes to your tour. A coach can read a surgeon''s note and turn it into a first week."],["Start in the warm pool","The Dobson therapy pool stays at 90 to 92°F. The water holds your weight, so a sore knee or hip can move without load. Ten easy minutes is a good first day."],["Pick Mobility 30, not a hard class","Thirty minutes of joint prep at intensity 1. You choose the range. Nobody needs you to touch your toes."],["Keep a short log","Write one line a day: what you did, how it felt the next morning. Your coach reads it before the second session."],["Add one thing a week","A second class, a longer swim, a little load. If a week feels like too much, repeat it. That is allowed."]]'::jsonb),
  ('what-to-eat-before-a-6-am-class', '2026-09-28', 'What to eat before a 6:00 a.m. class', 'A banana, some salt, and water. A short guide for people who do not wake up hungry.', 'Eat and recover', 'nadia-kowalski', 4, 'gold', 'Café counter at Dobson, early morning', 'rhythm-ride', '[["If you can eat, eat small","Half a banana or a slice of toast, 30 to 45 minutes before class. Skip anything heavy or fried."],["If you cannot, drink","A glass of water and a pinch of salt is enough for a 45-minute class. Your body has fuel for it."],["Coffee is fine","One cup is fine. Two on an empty stomach and a hard interval class is a bad mix."],["Eat after","Within an hour, add protein and something with carbohydrate. Eggs and fruit. Yogurt and oats. The Dobson café opens at 6:00 a.m."],["Watch the heat","From June to September, add a second glass of water to your morning. Sweat in a dry climate disappears fast."]]'::jsonb),
  ('packing-for-kids-club', '2026-09-20', 'Packing for kids club, in 5 minutes', 'Socks, a water bottle and a note about allergies. Here is the rest.', 'Families', 'luis-ortega', 3, 'rose', 'Kids club check-in door, Val Vista', 'kids-club', '[["Socks and a water bottle","Children play barefoot or in socks. Label the bottle. We refill it."],["One change of clothes","Spills and splash pad days happen. A small bag with a dry set saves a bad evening."],["Tell us about allergies","Add allergy and medical notes in the app before you arrive. The staff read them at check-in."],["Check in at the same club","Kids club blocks are 2 hours, and you stay in the building. An unclaimed block is released 15 minutes after it starts."],["Plan your own two hours","Book a class that fits inside the block, with time to shower. Most parents pick a 45-minute class and a swim."]]'::jsonb),
  ('heritage-rooftop-deck-open', '2026-09-12', 'The Heritage rooftop deck is open to all members', 'Mobility sessions at golden hour, Tuesday to Saturday.', 'Club news', 'devon-hart', 2, 'plum', 'Rooftop mobility deck at golden hour', 'mobility-30', '[["What opened","The rooftop mobility deck at Gilbert – Heritage is open to every member, not only Summit. Mats, bands and foam rollers are up there."],["When to go","Mobility 30 runs at golden hour, Tuesday to Saturday. In October the light is soft from about 5:30 p.m."],["What to bring","Water and a layer. The deck is in the open air and it cools quickly after the sun drops."],["Access","A lift and stairs reach the deck. Both are step-free from the lobby."],["Rules","No lifting on the deck. Phones stay in your pocket during class. The deck closes at 8:00 p.m."]]'::jsonb),
  ('pickleball-in-the-heat', '2026-08-30', 'Pickleball in the heat: a short guide', 'Play early, drink before you are thirsty, and use the shade sails.', 'Train', 'ray-delgado', 5, 'copper', 'Red Mountain courts at 6:30 a.m.', 'pickleball-open-play', '[["Play before 9:00 a.m.","From June to September the courts are comfortable before 9:00 a.m. and hard work after 11:00. Book the early slot."],["Drink before you are thirsty","A cup of water every two games. By the time you are thirsty you are already behind."],["Use the shade","Red Mountain''s courts have shade at the north end after 7:30 a.m. Swap ends so nobody plays in the sun all game."],["Dress for it","Light colors, a hat between points, and sunscreen on your ears. Bring a spare shirt for the end of a long session."],["Know when to stop","Dizziness, a headache or cramps mean sit down and drink. Tell the desk. The recovery lounge is a good place to cool off."]]'::jsonb);
