  ('club_quotes', '[{"quote":"Swim school got my daughter from ''no'' to Level 3 in one summer.","who":"Maya T.","goal":"Family of four"},{"quote":"I lift at 5:00 a.m. and the cycle studio is full at 6:00. Both are good problems.","who":"Jess R.","goal":"Ridge member"},{"quote":"Teen Strength gave my son a place that is not a screen.","who":"Carlos M.","goal":"Parent"}]'::jsonb),
